    {
      "type": "color",
      "id": "text_color",
      "default": "#FFFFFF",
      "label": "Text color"
    },
    {
      "type": "color",
      "id": "button_color",
      "default": "#f39c12",
      "label": "Button color"
    },
    {
      "type": "color",
      "id": "button_text_color",
      "default": "#FFFFFF",
      "label": "Button text color"
    }
  ],
  "max_blocks": 5,
  "blocks": [
    {
      "type": "slide",
      "name": "Slide",
      "settings": [
        {
          "type": "image_picker",
          "id": "image",
          "label": "Desktop image"
        },
        {
          "type": "image_picker",
          "id": "mobile_image",
          "label": "Mobile image",
          "info": "Uses the desktop image if left blank."
        },
        {
          "type": "text",
          "id": "theme_asset",
          "label": "Desktop theme asset filename",
          "info": "Optional asset from /assets, for example hero-family-garden.jpg"
        },
        {
          "type": "text",
          "id": "mobile_theme_asset",
          "label": "Mobile theme asset filename",
          "info": "Uses the desktop theme asset if left blank."
        },
        {
          "type": "text",
          "id": "image_alt",
          "label": "Image alt text"
        },
        {
          "type": "text",
          "id": "desktop_object_position",
          "default": "center center",
          "label": "Desktop image position",
          "info": "CSS object-position value, for example 62% center."
        },
        {
          "type": "text",
          "id": "mobile_object_position",
          "default": "center center",
          "label": "Mobile image position",
          "info": "CSS object-position value, for example 70% center."
        }
      ]
    }
  ],
  "presets": [
    {
      "name": "Hero Banner"
    }
  ]
